      "th": "ลากลำดับทางด้านซ้ายเพื่อจัดเรียงใหม่ JSON มี prompts และ prompt_order เพื่อให้คุณสามารถคัดลอกไว้ข้างๆ ค่าที่ตั้งไว้ล่วงหน้าของ SillyTavern ไม่ใช่พรีเซ็ตโมเดลแบบเต็ม"
