      "th": "หลังจากที่คุณเขียนรูปแบบแล้ว สิ่งนี้จะดำเนินไปตามลำดับ: ตัวอักษร, Escape, คลาส, Anchors, ปริมาณ, การสลับกัน, กลุ่ม และ Flags"
