      "ko": "SillyTavern v2 카드를 작성하세요. JSON 또는 PNG를 내보내고 문자 목록에서 가져옵니다.",
      "th": "เขียนการ์ด SillyTavern v2 ส่งออก JSON หรือ PNG และนำเข้าจากรายการอักขระ"
