      "th": "ที่ตั้งไว้ล่วงหน้า “{name}” จะส่งออกบล็อก {count} prompts เก็บข้อความ prompt_order เก็บคำสั่งซื้อนี้ ไม่รวมรุ่นหรืออุณหภูมิ"
